
cc.Class({
    extends: cc.Component,

    properties: {
        _playUnlockState:0, 
        _clickPyramidiconState:0,
        _needBonusState:0,   
        _targetPos:cc.v2(23,7),
        _defautPos:cc.v2(23,150),
    },
    onLoad () {
        this._tips = cc.find('slots/mask/tips',this.node.parent);
        this._points = cc.find('points',this.node);
        let btn_unlock = cc.find('btn_unlock/operate',this.node)
        Global.btnClickEvent(btn_unlock,this.onClicklock,this)

        let btn_pyramidicon = cc.find('slots/pyramidicon',this.node.parent)
        Global.btnClickEvent(btn_pyramidicon,this.onClickpyramidicon,this)

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_REFUSH_ENERGY,this.onEventRefushEnergy,this)
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,this.onChangeBetValue,this)

    },

    start () {
        //当前押注是否足够解锁
        let superbonus = cc.vv.gameData.getSuperBonus();
        //解锁节点的显示/隐藏
        this.UNLOCKVAL = superbonus.min;
        this.updateShow();
        this.updateNeedBonusNum();
        this.updateCoinProgress(superbonus)
    },

     //初始化显示
     updateShow:function(){
        let betIdx = cc.vv.gameData.GetBetIdx()
        let ani_node = cc.find('btn_unlock',this.node)
        
        if(betIdx >= this.UNLOCKVAL){
            //解锁
            if(this._playUnlockState != 1){
                this._playUnlockState = 1
                this.playTips();
                Global.SlotsSoundMgr.playEffect('unlock');
                cc.vv.gameData.playSpine(ani_node,'animation3',false,()=>{
                    ani_node.active = false;
                 }) 
            }
        }
        else{
            //锁定
            if(this._playUnlockState != 2){
                this._playUnlockState = 2
                ani_node.active = true;
                this.playTips();
                Global.SlotsSoundMgr.playEffect('lock');
                cc.vv.gameData.playSpine(ani_node,'animation1',false,()=>{
                    cc.vv.gameData.playSpine(ani_node,'animation2',false,null);
                 }) 
            }
        }
    },

    //解锁时播放tips
    playTips(){
        this._clickPyramidiconState = 1;
        this._tips.stopAllActions();
        let delay = cc.delayTime(5);
        let showtips = cc.moveTo(0.3,cc.v2(23,7)).easing(cc.easeBackOut());
        let hidetips = cc.moveTo(0.3,cc.v2(23,150)).easing(cc.easeBackIn());
        let seq = cc.sequence(showtips,delay,hidetips);
        this._tips.runAction(seq);
    },

    //点击解锁
    onClicklock:function(){
        if(cc.vv.gameData.isReelMove())
            return;
        if(this._playUnlockState == 1)
            return;
        //更新押注额
        cc.vv.gameData.GetBottomScript().SetBetIdx(this.UNLOCKVAL)
        //然后播放解锁表现
        let ani_node = cc.find('btn_unlock',this.node)
        cc.vv.gameData.playSpine(ani_node,'animation3',false,()=>{
            ani_node.active = false;
        })
    },

    //点击图标打开tips
    onClickpyramidicon:function(){
        Global.SlotsSoundMgr.playEffect('tip_show');
        clearTimeout(this._timeoutId);
        if(this._clickPyramidiconState == 0){
            this.playTips();
        }else{
            this._clickPyramidiconState = 0;
            cc.tween(this._tips).to(0.3,{position:this._defautPos},{easing:'backIn'}).start();
        }
    },

    updateCoinProgress:function(superbonus,isinit=true){
        if(superbonus){
            if(isinit||superbonus.num==0){
                for(let i=1;i<11;i++){
                    let pointnode = cc.find(cc.js.formatStr('points/point%s/coin',i),this.node);
                    pointnode.active = superbonus.num>=i?true:false;
                }
            }else{
                let pnode = cc.find(cc.js.formatStr('points/point%s/coin',superbonus.num),this.node);
                let spnode = cc.find(cc.js.formatStr('points/point%s/spine',superbonus.num),this.node);
                pnode.active = true;
                pnode.scale = 0;
                cc.vv.gameData.playSpine(spnode,'animation1',false,null);
                cc.tween(pnode).to(0.5,{scale:1},{easing:'backInOut'}).call(()=>{
                    if(superbonus.total == superbonus.num){
                        //播放收集慢特效
                        let fullspine = cc.find('collectfull',this.node);
                        Global.SlotsSoundMgr.playEffect('trail_full');
                        cc.vv.gameData.playSpine(fullspine,'animation',false,()=>{
                            fullspine.active = false;
                        })
                        //打开super免费开始界面
                        this.scheduleOnce(() => {
                            cc.vv.gameData.GetUIManager().showSuperFreeStartUI();
                        }, 1);
                    }else{
                        Global.SlotsSoundMgr.playEffect('trail_in');
                    }
                }).start();
            }
        }
    },

    //更新进入转盘游戏需要的bonus数量
    updateNeedBonusNum(isinit=true){
        let needbet = 13;
        let betIdx = cc.vv.gameData.GetBetIdx()
        if(betIdx < needbet){
            //需求7
            if(this._needBonusState!=7){
                this._needBonusState = 7;
                Global.SlotsSoundMgr.playEffect('low_bet');
                this.playChangeBonusNumSp(isinit,'animation1',()=>{
                    cc.find('triggersui6',this.node).active = false;
                    cc.find('triggersui7',this.node).active = true;
                });
            }

        }else{
            //需求6
            if(this._needBonusState!=6){
                this._needBonusState = 6;
                Global.SlotsSoundMgr.playEffect('high_bet');
                cc.find('triggersui7',this.node).active = false;
                cc.find('triggersui6',this.node).active = true;
                this.playChangeBonusNumSp(isinit,'animation2',null);
            }
        }
    },

    //播放改变bonus数量动画
    playChangeBonusNumSp(isinit,aniname,endcall){
        if(!isinit){
            let spnode = cc.find('betchange',this.node);
            cc.vv.gameData.playSpine(spnode,aniname,false,endcall);
        }
    },

    //押注额改变val
    onChangeBetValue(data){
        this.updateShow();
        this.updateNeedBonusNum(false);
    },

    //刷新收集数量
    onEventRefushEnergy:function(){
        //播放能量改变spine
        this.scheduleOnce(() => {
            let superbonus = cc.vv.gameData.getSuperBonus();
            this.updateCoinProgress(superbonus,false)
        }, 0.3);
    },
});
