
cc.Class({
    extends: require('LMSlots_GameData_Base'),

    properties: {

    },

    //deskInfo进入游戏获得的服务端数据
    init(deskInfo,gameId,gameJackpot){
        this._selectData = deskInfo.select;
        this._bonusGame = deskInfo.bonusGame;
        this._collect = deskInfo.freeGameData.collect;
        this._slotsList = deskInfo.freeGameData.slotsList;
        this._freeCnt = deskInfo.restFreeCount;
        this._superBonus = deskInfo.superbonus;
        //this.needBet = deskInfo.collectFree.min;
        this._super(deskInfo,gameId,gameJackpot);
     },

     //注册event
    RegisterEvent(){
        this._super();
        this._EventId.GORGEOUSCLEOPATRA_UNLOCK_ENERGY = 'GORGEOUSCLEOPATRA_UNLOCK_ENERGY'
    },

     OnRcvNetSpine:function(msg){
        //msg = {"c":44,"code":200,"betcoin":90000,"wincoin":0,"allFreeCnt":0,"pyramid":{"before":222,"info":{"idx_7":8,"idx_9":15,"idx_2":2,"idx_16":8,"idx_5":12,"idx_1":2,"idx_18":10,"idx_8":15,"idx_12":17,"idx_4":5},"after":316},"addMult":1,"mults":[10000,20000,30000,40000,50000,60000,70000,80000,90000],"lastBetCoin":353000,"coin":353000,"nextBetLine":{"spcode":500},"select":{"state":false},"spcode":200,"pooljp":0,"freeResult":{"freeInfo":[],"triFreeCnt":0},"scatterZJLuXian":{"indexs":[],"mult":0,"coin":0},"subGameInfo":{"subGamid":-1,"isMustJoin":-1},"zjLuXian":[],"freeCnt":0,"resultCards":[12,5,8,11,12,12,10,8,8,12,10,10,2,8,4,10,10,5,9,4],"freeWinCoin":0,"spEffect":{"wincoin":0,"kind":0},"spLuXian":0}
        if(msg.code == 200){
            this._selectData = msg.select; 
            this._bonusGame = msg.bonusGame;
            this._collect = msg.collect;
            this._slotsList = msg.slotsList;
            this._freeCnt = msg.freeCnt;
            this._superBonus = msg.superbonus;
            this._super(msg);
            this._moreSlotsMgr.showSpineResult(msg);
        }
    },

    //按节点播放spine
    playSpine:function(node,aniName,loop,endCall){
        if(node){
            node.active = true
            let ske = node.getComponent(sp.Skeleton)
            if(ske){
                ske.setAnimation(0,aniName,loop)
                ske.setCompleteListener(() => {
                    if(endCall){
                        endCall()
                    }
                })
            }
        }
        
    },

    //是否旋转中
    isReelMove(){
        return this._isReelMove||this._autoTime>0;
    },

    //设置reel移动中
    setReelMove(ismove){
        this._isReelMove = ismove;
    },
    
    //设置superbonus
    setSuperBonus(spbonus){
        this._superBonus = spbonus;
    },

    //获取superbonus数据
    getSuperBonus(){
        return this._superBonus;
    },

    //清除collect数据
    clearSuperBonus(){
        this._superBonus.num = 0;
    },

    //获取freeCnt
    getFreeCnt(){
        return  this._freeCnt;
    },

    //获取bonus数据
    getBonusData:function(){
        return this._bonusGame;
    },

    //获取select数据
    getSelectData:function(){
        return this._selectData;
    },

    //设置免费游戏脚本
    SetGameScript:function(fgame){
        this._freeGame = fgame
    },

    GetFreeGameScript:function(){
        return this._freeGame
    },

    //设置ui管理脚本
    SetUIManagerScript:function(uimgr){
        this._uimgr = uimgr;
    },

    GetUIManager:function(){
        return this._uimgr;
    },

    //设置more slots管理
    SetMoreSlotsMgr:function(slotsmgr){
        this._moreSlotsMgr = slotsmgr;
    },

    //获取moreslotsmgr
    getMoreSlotsMgr(){
        return this._moreSlotsMgr;
    },

    //转盘数据
    SetWheelData(wheeldata){
        this._wheelData = wheeldata;
    },

    getWheelData(){
        return this._wheelData;
    },

    //清除wheeldata
    clearWheelData(){
        this._wheelData = null;
    },

    //获取slotslist数据
    getSlotsListData(){
        return this._slotsList;
    },

    //获取collect
    getCollectData(){
        return this._collect;
    },



    //是否触发普通免费 
    isTriggerNormalFree: function(){
        let triggerfree = (this._gameInfo.freeResult.freeInfo.idxs&&this._gameInfo.freeResult.freeInfo.idxs.length>0);
        if(triggerfree){
            return this._gameInfo.freeResult.freeInfo.freeCnt;
        }
        return 0;
    },

    //从转盘数据获取免费次数 如果为0表示没有触发免费游戏
    getWheelFreeTimes(){
        let freetimes = 0;
        if(this._wheelData){
            if(this._wheelData.result.length==1&&this._wheelData.result[0].type == 'FREE'){
                freetimes = this._wheelData.result[0].num;
            }else if(this._wheelData.result.length>1&&this._wheelData.result[1].type == 'FREE'){
                freetimes = this._wheelData.result[1].num;
            }
        }
        return freetimes;
    }
});
