//游戏UI管理
cc.Class({
    extends: cc.Component,

    properties: {
        
    },

    onLoad () {
        this._luckUI = cc.find('luckui',this.node);
        this._wheelresultUI = cc.find('wheelresultui',this.node);
        this._startfreeUI = cc.find('startfreegameui',this.node);
        this._collectfreeUI = cc.find('collectui',this.node);
        this._startSuperfreeUI = cc.find('startsuperfreegameui',this.node);
        this._collectSuperfreeUI = cc.find('supercollectui',this.node);
        this._extrafreeUI = cc.find('extrafreeui',this.node);
        this._extrasuperfreeUI = cc.find('extrasuperfreeui',this.node);

        let btn_collect = cc.find('mainnode/btn_collect',this._wheelresultUI)
        Global.btnClickEvent(btn_collect,this.onCollectCoin,this)
        let btn_start = cc.find('mainnode/btn_start',this._startfreeUI)
        Global.btnClickEvent(btn_start,this.onStartFreeGame,this)
        let btn_freeovercollect = cc.find('mainnode/btn_start',this._collectfreeUI);
        Global.btnClickEvent(btn_freeovercollect,this.onFreeOverCollect,this)
        let btn_superstart = cc.find('mainnode/btn_start',this._startSuperfreeUI)
        Global.btnClickEvent(btn_superstart,this.onSuperFreeStart,this)
        let btn_supercollect = cc.find('mainnode/btn_start',this._collectSuperfreeUI)
        Global.btnClickEvent(btn_supercollect,this.onSuperFreeOverCollect,this)
        
    },

    start () {

    },

    //显示luck界面
    showLuckyUI(endcall){
        this._luckUI.active = true;
        Global.showAlertAction(this._luckUI,true,0.01,1,()=>{
            this.scheduleOnce(() => {
                Global.SlotsSoundMgr.playEffect('popup_out');
                Global.showAlertAction(this._luckUI,false,1,0,endcall);
            }, 2);
        })
    },

    //显示扩展界面
    async showExtraFreeUI(){
        return new Promise((success)=>{
            let slotslist = cc.vv.gameData.getSlotsListData();
            if(!slotslist){
                success();
            }else{
                if(slotslist.free > 0){
                    let superbonus = cc.vv.gameData.getSuperBonus();
                    if(superbonus){
                        let shownode = superbonus.total==superbonus.num?this._extrasuperfreeUI:this._extrafreeUI;
                        let mainnode = cc.find('mainnode',shownode);
                        shownode.active = true;
                        cc.find('freegames/middle/freetimes',mainnode).getComponent(cc.Label).string = slotslist.free;
                        Global.showAlertAction(mainnode,true,0.01,1,()=>{
                            this.scheduleOnce(() => {
                                Global.showAlertAction(mainnode,false,1,0,()=>{
                                    shownode.active = false;
                                    success();
                                });
                            }, 2);
                        })
                    }
                }else{
                    success();
                }
            }
        })
    },

    //显示转盘结果界面 type1倍率 2jackpot 3
    showWheelResultUI(data){
        this._wheelData = data;
        let result = data.result;
        this._wheelresultUI.active = true;
        let mainnode = cc.find('mainnode',this._wheelresultUI);
        if(result.length == 1){
            if(result[0].type== 'MULT'){
                this.showMultUI(result[0].num,data.gamewin);
            }else if(result[0].type == 'FREE'){
                this.showFreeUI(result[0].num);
            }
        }else{
            //两次中奖
            this.showJackpotUI(result[0],result[1],data.gamewin);
        }

        let self = this
        Global.showAlertAction(mainnode,true,0.01,1,()=>{
            let totalwin = cc.find('mainnode/bottom/totalwin',self._wheelresultUI);
            Global.doRoallNumEff(totalwin,data.wincoin,data.wincoin,0,null,null,0,true);
        });

        let btn_collect = cc.find('mainnode/btn_collect',this._wheelresultUI)
        cc.vv.gameData.checkAutoPlay(btn_collect, ()=>{
            Global.SlotsSoundMgr.playEffect('btn_click');
            let mainnode = cc.find('mainnode',this._wheelresultUI);
            cc.tween(mainnode).to(0.1,{scale:1.2}).to(0.3,{scale:0},{easing:"backOut"}).call(()=>{
                if(this._wheelData.select&&this._wheelData.select.state){
                    //如果需要操作
                    this.sendEnterFreeeGame(this._wheelData.select.rtype);
                }else{
                    cc.find('Canvas/safe_node/subgamewheel').getComponent('TheMagicHanzo_Wheel').wheelResultUIClose();
                }
                this._wheelresultUI.active = false;
            }).start();
        });
    },

    //显示jackpot数据(两种情况 中免费 中mult)
    showJackpotUI(result1,result2,gamewin){
        this.showSubUI(true,false,false);
        //显示免费
        let mult = cc.find('mainnode/jackpot/middle_mult',this._wheelresultUI);
        let free = cc.find('mainnode/jackpot/middle_free',this._wheelresultUI);
        let totalwinnode = cc.find('mainnode/jackpot/totalwin',this._wheelresultUI);

        //更改jackpot名
        let headnode = cc.find('mainnode/jackpot/head',this._wheelresultUI);
        let spname = this.getJackpotSpName(result1.num);
        headnode.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("popup").getSpriteFrame(spname);

        if(result2.type == 'MULT'){
            //显示mult
            cc.find('multnum',mult).getComponent(cc.Label).string = result2.num+'X';
            //let totalwin = cc.find('totalwin',mult);
           // totalwin.getComponent(cc.Label).string = Global.convertNumToShort(gamewin,1000,0);
            this.setShortNum(cc.find('totalwin',mult),gamewin);
            totalwinnode.active = true;
            mult.active = true;
            free.active = false;
        }else if(result2.type == 'FREE'){
            cc.find('freetimes',free).getComponent(cc.Label).string = result2.num;
            totalwinnode.active = false;
            free.active = true;
            mult.active = false;
        } 
    },

    setShortNum(node,wincoin){
        if(wincoin > 1000){
            node.getComponent(cc.Label).string = Global.FormatNumToComma(Number(wincoin/1000))+'K';
        }else{
            node.getComponent(cc.Label).string = wincoin;
        }
    },

    //获取jackpot名
    getJackpotSpName(pool){
        switch (pool) {
            case 1:return 'theme143_popup_text7_4';
            case 2:return 'theme143_popup_text7_3';
            case 3:return 'theme143_popup_text7_2';
            case 4:return 'theme143_popup_text7_1';
        }
    },

    //显示mult
    showMultUI(num,gamewin){
        Global.SlotsSoundMgr.playEffect('tip_show');
        this.showSubUI(false,true,false);
        let mult = cc.find('mainnode/mult',this._wheelresultUI);
        cc.find('multnum',mult).getComponent(cc.Label).string = num+'X';
        let totalwin = cc.find('middle/totalwin',mult);
        //totalwin.getComponent(cc.Label).string = Global.convertNumToShort(gamewin,1000,0);
        this.setShortNum(totalwin,gamewin);
    },

    //显示free
    showFreeUI(num){
        Global.SlotsSoundMgr.playEffect('tip_show');
        this.showSubUI(false,false,true);
        let free = cc.find('mainnode/freegames/middle/freetimes',this._wheelresultUI);
        free.getComponent(cc.Label).string = num;
    },

    showSubUI(pool,mult,free){
        Global.SlotsSoundMgr.playEffect('tip_show');
        let jackpotnode = cc.find('mainnode/jackpot',this._wheelresultUI);
        let multnode = cc.find('mainnode/mult',this._wheelresultUI);
        let freenode = cc.find('mainnode/freegames',this._wheelresultUI);
        jackpotnode.active = pool;
        multnode.active = mult;
        freenode.active = free;
    },

    //显示开始免费游戏界面
    showStartFreeGameUI(freetimes){
        Global.SlotsSoundMgr.playEffect('free_popup_trigger');
        this._startfreeUI.active = true;
        let mainnode = cc.find('mainnode',this._startfreeUI);
        cc.find('freegames/middle/freetimes',mainnode).getComponent(cc.Label).string = freetimes;
        Global.showAlertAction(mainnode,true,0.01,1,null);

        let btn_start = cc.find('mainnode/btn_start',this._startfreeUI)
        cc.vv.gameData.checkAutoPlay(btn_start, ()=>{
            Global.SlotsSoundMgr.playEffect('btn_click');
            let mainnode = cc.find('mainnode',this._startfreeUI);
            cc.tween(mainnode).to(0.1,{scale:1.2}).to(0.3,{scale:0},{easing:"backOut"}).call(()=>{
                this._startfreeUI.active = false;
                cc.log("2222222222222222222222222222222");
                cc.vv.gameData.GetSlotsScript().startEnterFreeGame();
            }).start();
        });
    },

    //显示super免费开始界面
    showSuperFreeStartUI(){
        Global.SlotsSoundMgr.playEffect('free_popup_trigger');
        this._startSuperfreeUI.active = true;
        let freetimes = cc.vv.gameData.isTriggerNormalFree()||cc.vv.gameData.getWheelFreeTimes();
        let mainnode = cc.find('mainnode',this._startSuperfreeUI);
        cc.find('freegames/middle/freetimes',mainnode).getComponent(cc.Label).string = freetimes;
        Global.showAlertAction(mainnode,true,0.01,1,null);

        let btn_superstart = cc.find('mainnode/btn_start',this._startSuperfreeUI)
        cc.vv.gameData.checkAutoPlay(btn_superstart, ()=>{
            Global.SlotsSoundMgr.playEffect('btn_click');
            let mainnode = cc.find('mainnode',this._startSuperfreeUI);
            cc.tween(mainnode).to(0.1,{scale:1.2}).to(0.3,{scale:0},{easing:"backOut"}).call(()=>{
                this._startSuperfreeUI.active = false;
                cc.vv.gameData.getMoreSlotsMgr().changeBackimage(1);
                cc.vv.gameData.GetSlotsScript().startEnterFreeGame();
            }).start();
        })
    },

    //显示super免费结束界面
    showSuperFreeCollectUI(){
        Global.SlotsSoundMgr.playEffect('free_popup_collect');
        this._collectSuperfreeUI.active = true;
        let mainnode = cc.find('mainnode',this._collectSuperfreeUI);
        Global.showAlertAction(mainnode,true,0.01,1,()=>{
            let lbl_coin = cc.find('freegames/middle/collectcoin',mainnode);
            let freewincoin = cc.vv.gameData.GetGameTotalFreeWin();
            lbl_coin.getComponent(cc.Label).string = '';
            Global.doRoallNumEff(lbl_coin,0,freewincoin,1,null,null,0,true);
        })

        let btn_supercollect = cc.find('mainnode/btn_start',this._collectSuperfreeUI)
        cc.vv.gameData.checkAutoPlay(btn_supercollect, ()=>{
            Global.SlotsSoundMgr.playEffect('btn_click');
            cc.vv.gameData.clearSuperBonus();
            let mainnode = cc.find('mainnode',this._collectSuperfreeUI);
            cc.tween(mainnode).to(0.1,{scale:1.2}).to(0.3,{scale:0},{easing:"backOut"}).call(()=>{
                this._collectSuperfreeUI.active = false;
                cc.vv.gameData.GetSlotsScript().exitFreeGame();
            }).start();
        })
    },

    //显示结束免费collect界面
    showFreeOverCollectUI(){
        Global.SlotsSoundMgr.playEffect('free_popup_collect');
        let superbonus = cc.vv.gameData.getSuperBonus();
        if(superbonus){
            if(superbonus.total == superbonus.num){
                this.showSuperFreeCollectUI();
                return;
            }
        }

        this._collectfreeUI.active = true;
        let mainnode = cc.find('mainnode',this._collectfreeUI);
        Global.showAlertAction(mainnode,true,0.01,1,()=>{
            let lbl_coin = cc.find('freegames/middle/collectcoin',mainnode);
            let freewincoin = cc.vv.gameData.GetGameTotalFreeWin();
            lbl_coin.getComponent(cc.Label).string = '';
            Global.doRoallNumEff(lbl_coin,0,freewincoin,1,null,null,0,true);
        })

        let btn_freeovercollect = cc.find('mainnode/btn_start',this._collectfreeUI);
        cc.vv.gameData.checkAutoPlay(btn_freeovercollect, ()=>{
            Global.SlotsSoundMgr.playEffect('btn_click');
            let mainnode = cc.find('mainnode',this._collectfreeUI);
            cc.tween(mainnode).to(0.1,{scale:1.2}).to(0.3,{scale:0},{easing:"backOut"}).call(()=>{
                this._collectfreeUI.active = false;
                cc.vv.gameData.GetSlotsScript().exitFreeGame();
            }).start();
        });
    },

    //super免费开始
    onSuperFreeStart(){
        let btn_superstart = cc.find('mainnode/btn_start',this._startSuperfreeUI)
        btn_superstart.stopAllActions();
        Global.SlotsSoundMgr.playEffect('btn_click');
        let mainnode = cc.find('mainnode',this._startSuperfreeUI);
        cc.tween(mainnode).to(0.1,{scale:1.2}).to(0.3,{scale:0},{easing:"backOut"}).call(()=>{
            this._startSuperfreeUI.active = false;
            cc.vv.gameData.getMoreSlotsMgr().changeBackimage(1);
            cc.vv.gameData.GetSlotsScript().startEnterFreeGame();
        }).start();
    },

    //免费结束collect界面点击collect
    onFreeOverCollect(){
        let btn_freeovercollect = cc.find('mainnode/btn_start',this._collectfreeUI);
        btn_freeovercollect.stopAllActions();
        Global.SlotsSoundMgr.playEffect('btn_click');
        let mainnode = cc.find('mainnode',this._collectfreeUI);
        cc.tween(mainnode).to(0.1,{scale:1.2}).to(0.3,{scale:0},{easing:"backOut"}).call(()=>{
            this._collectfreeUI.active = false;
            cc.vv.gameData.GetSlotsScript().exitFreeGame();
        }).start();
    },

    //super免费结束点击collect
    onSuperFreeOverCollect(){
        let btn_supercollect = cc.find('mainnode/btn_start',this._collectSuperfreeUI)
        btn_supercollect.stopAllActions();
        Global.SlotsSoundMgr.playEffect('btn_click');
        cc.vv.gameData.clearSuperBonus();
        let mainnode = cc.find('mainnode',this._collectSuperfreeUI);
        cc.tween(mainnode).to(0.1,{scale:1.2}).to(0.3,{scale:0},{easing:"backOut"}).call(()=>{
            this._collectSuperfreeUI.active = false;
            cc.vv.gameData.GetSlotsScript().exitFreeGame();
        }).start();
    },

    //转盘收集金币事件
    onCollectCoin(){
        let btn_collect = cc.find('mainnode/btn_collect',this._wheelresultUI)
        btn_collect.stopAllActions();
        Global.SlotsSoundMgr.playEffect('btn_click');
        let mainnode = cc.find('mainnode',this._wheelresultUI);
        cc.tween(mainnode).to(0.1,{scale:1.2}).to(0.3,{scale:0},{easing:"backOut"}).call(()=>{
            if(this._wheelData.select&&this._wheelData.select.state){
                //如果需要操作
                this.sendEnterFreeeGame(this._wheelData.select.rtype);
            }else{
                cc.find('Canvas/safe_node/subgamewheel').getComponent('TheMagicHanzo_Wheel').wheelResultUIClose();
            }
            this._wheelresultUI.active = false;
        }).start();
    },


    //转盘开始免费游戏事件
    onStartFreeGame(){
        let btn_start = cc.find('mainnode/btn_start',this._startfreeUI)
        btn_start.stopAllActions();
        Global.SlotsSoundMgr.playEffect('btn_click');
        let mainnode = cc.find('mainnode',this._startfreeUI);
        cc.tween(mainnode).to(0.1,{scale:1.2}).to(0.3,{scale:0},{easing:"backOut"}).call(()=>{
            this._startfreeUI.active = false;
            cc.log("11111111111111111111111111111");
            cc.vv.gameData.GetSlotsScript().startEnterFreeGame();
        }).start();
    },

    //发送进入小游戏 51消息头
    sendEnterFreeeGame(type){
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.data = {}
        req.data.rtype = type
        req.gameid = cc.vv.gameData.getGameId()
        cc.vv.NetManager.send(req,true);
    },
});
