
cc.Class({
    extends: cc.Component,

    properties: {
        _node_main: null,
        _node_wheel: null,
        _node_win: null,
        _targetIdx:0, //1~20
    },

    onLoad () {
        this._node_main = cc.find("mainnode", this.node);
        this._node_wheel = cc.find("node_wheel", this._node_main);
        this._node_win = cc.find("node_win", this._node_main);
        this._node_winSpine = cc.find("wheelNode/spinewining", this._node_wheel);
        this._node_morewinSpine = cc.find("wheelNode/morewiningspine", this._node_wheel);
        this._node_activewheel = cc.find("wheelNode/activewheel", this._node_wheel);

        this._btnSpin = cc.find('wheelNode/btnSpin',this._node_wheel);
        Global.btnClickEvent(this._btnSpin,this.onWheelStart,this)
        cc.vv.gameData.playSpine(this._btnSpin,'animation1',true,null);

    },

    start(){
        //测试
        //this.enterGame();
    },

    onEnable(){
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, this);
    },

    onDisable(){
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, false, this); 
    },


    //转盘开始旋转
    onWheelStart(btn){
        //开始旋转
        this._btnSpin.stopAllActions();
        btn.node.getComponent(cc.Button).interactable = false;
        Global.SlotsSoundMgr.playEffect('wheel_press');            
        cc.vv.gameData.GetUIManager().sendEnterFreeeGame(1);

        let spineSpinEff = cc.find('wheelNode/spineSpinEffect',this._node_wheel);
        cc.vv.gameData.playSpine(spineSpinEff,'animation',false,()=>{
            spineSpinEff.active = false;
        })
    },

    //进入游戏
    async enterGame (success) {
        this._nextStep = success;
        this._targetIdx = -1;
        this._node_winSpine.active = false;
        this._node_morewinSpine.active = false;
        this.clearWheelSubObject();
        this._btnSpin.getComponent(cc.Button).interactable = false;
        await this.showMain();
    },

    //退出游戏
    async exitGame () {
        await this.awaitTime(1.0);
        await this.playActions(this._node_main, [cc.scaleTo(0.2, 1.3), cc.scaleTo(0.5, 0)]);
        this._node_main.active = false;
    },

    //显示游戏主体
    async showMain () {
        return new Promise(async (success)=>{
            this._node_main.active = true;
            this._node_win.position = cc.v2(0,-225);
            this._node_win.scale = 0.6;
            this._node_wheel.scale = 0;
            this.showEnterGameWinCoin();
            Global.SlotsSoundMgr.playEffect('wheel_in');
            let rorationWheel = cc.find("wheelNode/rotationWheel", this._node_wheel);
            rorationWheel.angle = 126;
            await this.playActions(this._node_wheel, [cc.scaleTo(0.3, 1).easing(cc.easeBackInOut())]);
            await this.awaitTime(0.3);
            await this.playActions(this._node_win, [cc.moveTo(0.2,cc.v2(0,130)).easing(cc.easeBackInOut())]);
            this._btnSpin.getComponent(cc.Button).interactable = true;

            cc.vv.gameData.checkAutoPlay(this._btnSpin, ()=>{
                this._btnSpin.getComponent(cc.Button).interactable = false;
                Global.SlotsSoundMgr.playEffect('wheel_press');
                cc.vv.gameData.GetUIManager().sendEnterFreeeGame(1);

                let spineSpinEff = cc.find('wheelNode/spineSpinEffect',this._node_wheel);
                cc.vv.gameData.playSpine(spineSpinEff,'animation',false,()=>{
                    spineSpinEff.active = false;
                })
            })

            cc.vv.gameData.playSpine(this._btnSpin,'animation1',true);
            //下一步
            success();
        });
    },

    //显示进入转盘赢取的coin
    showEnterGameWinCoin(){
        let coinnode = cc.find('getcoin',this._node_win);
        let bonusdata = cc.vv.gameData.getBonusData();
        Global.doRoallNumEff(coinnode,0,bonusdata.gamewin,0,null,null,0,true);
    },

    //显示游戏结果(开始旋转)(服务器idx 1为mini)
    async showResult(resultidx){
        let rorationWheel = cc.find("wheelNode/rotationWheel", this._node_wheel);
        let offsetangle = rorationWheel.angle;
        if(this._targetIdx!=-1){
            //第二次旋转需要多加18度
            offsetangle = rorationWheel.angle%360-this._targetIdx*18;
        }
        this._targetIdx = resultidx - 1;
        let diffAngle = this._targetIdx*18;
        let targetAngle = -diffAngle - offsetangle;
        let mRound = 12; //转动圈数
        await this.awaitTime(1);
        //改变动画
        cc.vv.gameData.playSpine(this._btnSpin,'animation2',true,null);
        cc.find('wheelNode/spindisable',this._node_wheel).active = true;
        Global.SlotsSoundMgr.playEffect('wheel_spin');
        await this.playActions(rorationWheel, [
            cc.rotateTo(0.5*mRound, 360*mRound + targetAngle).easing(cc.easeSineInOut()),
        ]);
        //播放中奖效果
        if(this._wheelData.lucky){
            cc.vv.gameData.playSpine(this._node_morewinSpine,'animation1',true,null);
        }else{
            cc.vv.gameData.playSpine(this._node_winSpine,'animation',true,null);
        }
        Global.SlotsSoundMgr.playEffect('wheel_win');
        await this.awaitTime(2);
        //显示结算界面
        this.showResultUI();
    },

    //清除转盘子对象
    clearWheelSubObject(){
        let rotationWheel = cc.find("wheelNode/rotationWheel", this._node_wheel);
        rotationWheel.removeAllChildren();
    },

    //显示转盘结果界面
    showResultUI(){
        if(this._wheelData.lucky){
            //命中lucky
            Global.SlotsSoundMgr.playEffect('wheel_spin_again');
            cc.vv.gameData.GetUIManager().showLuckyUI(()=>{
                //lucky显示结束 播放激活spine
                Global.SlotsSoundMgr.playEffect('wheel_double');
                cc.vv.gameData.playSpine(this._node_activewheel,'animation',false,()=>{
                    //实例化morewinspine 作为转盘的字节点
                    let rorationWheel = cc.find("wheelNode/rotationWheel", this._node_wheel);
                    let instnode = cc.instantiate(this._node_morewinSpine);
                    instnode.parent = rorationWheel;
                    instnode.angle = -rorationWheel.angle;
                    cc.vv.gameData.playSpine(instnode,'animation2',true,null);
                    this._node_morewinSpine.active = false;
                    this._node_winSpine.active = false;
                    Global.SlotsSoundMgr.playEffect('wheel_win');
                    //还原btnspine
                    let btnspin = cc.find('wheelNode/btnSpin',this._node_wheel);
                    cc.vv.gameData.playSpine(btnspin,'animation1',true,null);
                    btnspin.getComponent(cc.Button).interactable = true;
                    cc.vv.gameData.checkAutoPlay(btnspin, ()=>{
                        btnspin.getComponent(cc.Button).interactable = false;
                        Global.SlotsSoundMgr.playEffect('wheel_press');
                        cc.vv.gameData.GetUIManager().sendEnterFreeeGame(1);

                        let spineSpinEff = cc.find('wheelNode/spineSpinEffect',this._node_wheel);
                        cc.vv.gameData.playSpine(spineSpinEff,'animation',false,()=>{
                            spineSpinEff.active = false;
                        })
                    })
                    cc.find('wheelNode/spindisable',this._node_wheel).active = false;
                });
            })
        }else{
            Global.SlotsSoundMgr.playEffect('wheel_popup');
            cc.vv.gameData.GetUIManager().showWheelResultUI(this._wheelData);       
        }
    },

    //转盘结果界面关闭
    wheelResultUIClose(){
        Global.SlotsSoundMgr.playEffect('wheel_in');
        cc.tween(this._node_win).to(0.3,{scale:0}).start();
        cc.tween(this._node_wheel).to(0.3,{scale:0}).call(()=>{
            this._node_main.active = false;
            cc.vv.gameData.GetSlotsScript().resetJackpot();
            if(this._nextStep){
                this._nextStep();
            }
        }).start();
    },

     //接收51消息返回
     onRcvSubGameAction:function(msg){
        // msg =  {"data":{"idx":1,"lucky":1,"select":{"state":false},"rtype":1,"wincoin":2300000,"state":true,"info":[{"idx":1,"num":150000,"type":"coin"},{"idx":5,"num":300000,"type":"coin"},{"idx":6,"num":500000,"type":"coin"},{"idx":10,"num":500000,"type":"coin"},{"idx":11,"num":300000,"type":"coin"},{"idx":12,"num":450000,"type":"coin"},{"idx":15,"num":100000,"type":"coin"}],"tri":{"min":13,"num1":7},"superbonus":{"min":3,"total":10,"num":5},"result":[{"num":1,"type":"POOL"}],"gamewin":2300000},"uid":104390,"c":51,"code":200}
        if(msg.code == 200){
            this._wheelData = msg.data;
            cc.vv.gameData.setSuperBonus(msg.data.superbonus);
            if(this._wheelData.rtype == 1){
                cc.vv.gameData.SetWheelData(msg.data);
                this.showResult(msg.data.idx);
            }else {
                this.wheelResultUIClose();
            }

        }
    },

    playActions (node, actionsArr) {
        return new Promise((success)=>{
            actionsArr.push(cc.callFunc(()=>{
                success();
            }));

            node.active = true;
            node.runAction(cc.sequence(actionsArr));
        });
    },

    awaitTime (time) {
        return new Promise((success)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },
});
