
//多slots管理
//分两种尺寸slots33/slots50
//slots50 w:+-150 h:200
//slots33 w:+-200 h:150

//不同等级开启slots数量
let SlotsCount = [3,6,12,18,18]
cc.Class({
    extends: cc.Component,

    properties: {
        bgs:[cc.SpriteFrame],
        _slotsScpList:[], 
        _curSlotsCount:0,           //当前slots总数 
        _curLevel:1,
        _curNum:0,            
    },

    onLoad () {
        let bgnode = cc.find('mainnode/bg',this.node);
        this._curBgSp = bgnode.getComponent(cc.Sprite);
        this._slotParNode = cc.find('mainnode/slotsnode',this.node);
        this._topcontentNode = cc.find('mainnode/topcontent',this.node);
        this._slots50 = cc.find('mainnode/slots50',this.node);
        this._slots33 = cc.find('mainnode/slots33',this.node);
    },

    start () {

    },

    //切换背景
    changeBackimage(index){
        this._curBgSp.spriteFrame = this.bgs[index];
    },

    //收集筹码效果(飞筹码效果)
    async collectBonusEffect(){
        return new Promise((success)=>{
            let collect = cc.vv.gameData.getCollectData();
            if(this._curNum == collect.num){
                success();
            }else{
                let mainnode = cc.find('mainnode',this.node);
                let bonusspine = cc.find('mainnode/collectbonus',this.node);
                let coinnode = cc.find('mainnode/topcontent/item1/aimnode',this.node);
                let collectspine = cc.find('mainnode/topcontent/item1/collectspine',this.node);
                let aimpos = mainnode.convertToNodeSpaceAR(coinnode.convertToWorldSpaceAR(cc.v2(0,0)))
                this._curNum = collect.num;
                this._slotsScpList.forEach(slots => {
                    slots.slotsFly(mainnode,aimpos,bonusspine);
                });
                Global.SlotsSoundMgr.playEffect('free_chip_collect');
                this.scheduleOnce(() => {  
                    this.updateCollectBounsNum();
                    cc.vv.gameData.playSpine(collectspine,'animation',false,null);
                }, 0.3);
                this.scheduleOnce(() => {  
                    success();
                }, 0.5);
            }
        })
    },

    //播放收集筹码达到固定数值后 升级(播放白框 再播放特效 更新slots数量)
    async bonusCollectUpgrade(){
        return new Promise((success)=>{
            let collect = cc.vv.gameData.getCollectData();
            if(this._curLevel == collect.level||collect.level>4){
                this.scheduleOnce(() => {
                    success();
                }, 0.1);
            }else{
                this.scheduleOnce(()=>{
                    //需要升级 延时1s显示
                    Global.SlotsSoundMgr.playEffect('free_message');
                    let spinenode = cc.find(cc.js.formatStr('mainnode/topcontent/item%s/upgradespine',collect.level),this.node);
                    cc.vv.gameData.playSpine(spinenode,'animation',false,()=>{
                        cc.vv.gameData.GetSlotsScript().playTransitionAni(()=>{
                            this._curLevel = collect.level;
                            this.scheduleOnce(() => {
                                success();
                            }, 0.5);
                        })
                        this.scheduleOnce(() => {
                            this.updateSlotsUI(false);
                        }, 0.2);
                    });
                },1);
            }
        })
    },

    //控制所有slots开始旋转
    startMove(){
        if(this._slotsScpList.length == 0)
            return;
        this._slotsScpList.forEach(slots => {
            slots.StartMove();
        });
    },

    //控制点击停止移动
    stopMove(){
        if(this._slotsScpList.length == 0)
            return;
        this._slotsScpList.forEach(slots => {
            slots.StopMove();
        });
    },

    //控制所有slots结果显示
    showSpineResult(msg){
        if(this._slotsScpList.length == 0)
            return;
        if(!msg.slotsList)
            return;
        let slotsinfo = msg.slotsList.info;
        for(let i=0;i<this._slotsScpList.length;i++){
            this._slotsScpList[i].showMsgSpineResult(msg,slotsinfo[i].resultCards);
        }
    },

    //控制slots播放赢的线路
    showWinTrance(){
        let slotslist = cc.vv.gameData.getSlotsListData();
        if(slotslist){
            for(let i=0;i<this._slotsScpList.length;i++){
                this._slotsScpList[i].ShowWinTraceResult(slotslist.info[i]);
                this._slotsScpList[i].updateWinCoin(slotslist.coins[i]);
            }
        }
    },

    //控制reelspine停止
    reelSpineEnd(reelidx){
        this._slotsScpList.forEach(slots => {
            slots.OnReelSpinEnd(reelidx)
            
            //不能判断，停下来的列等于总共的列，因为有时候只旋转了3列
            //停下来的列以及等于最后一列旋转的列，
            //说明整个列已经停止
            let lastReelStopIdx = slots.GetLastStopReelIdx()
            if(reelidx == lastReelStopIdx){
                //所有列都停止了
                slots.OnSpinEnd()
            }
        });

    },

    //加载slots界面/初始化默认符号 isinit为true表示初始化加载自动生成/false表示增加（总数12需要使用33规格slots）
    updateSlotsUI(isinit=true){

        let collect = cc.vv.gameData.getCollectData();
        let level = collect?collect.level:1;
        let num = collect?collect.num:0;
        let slotscount = SlotsCount[level-1];
        //如果是初始化或者升级后
        if(isinit||slotscount > this._curSlotsCount){
            this.dynamicLoadSlots(slotscount);
            //同时更新topcontent界面的高度
            this.updateTopContentPos(level,slotscount);
            this.updateCollectBounsNum();
            if(isinit){
                this._curLevel = level;
                this._curNum = num;
            }
        }
        if(isinit){
            //初始化时是superfree
            let superbonus = cc.vv.gameData.getSuperBonus();
            if(superbonus){
                if(superbonus.total == superbonus.num){
                    this.changeBackimage(1);
                }else{
                    this.changeBackimage(0);
                }
            }
        }
    },

    //动态加载slots(初始化或者升级时)
    dynamicLoadSlots(slotscount){
        this.clearSlotsUI();
        let loadtimes = 0;
        let self = this;
        let loadslots = function(){
            if(slotscount > 6){
                //使用50实例化
                self.initSlotsUI(self._slots33,loadtimes,3);
            }else{
                //使用33实例化
                self.initSlotsUI(self._slots50,loadtimes,2,slotscount);
            }
            loadtimes++;
            if(loadtimes < slotscount){
                self.scheduleOnce(() => {
                    loadslots();
                }, 0.03);
            }
        }
        loadslots();
    },

    //更新收集bonus图标数量
    updateCollectBounsNum(){
        let collect = cc.vv.gameData.getCollectData();
        let num = collect?collect.num:0;
        let coinnode = cc.find('mainnode/topcontent/item1/coin',this.node);
        coinnode.getComponent(cc.Label).string = num;
    },

    //更新topcontent界面高度
    updateTopContentPos(level,slotscount){
        if(level > 2){
            this._topcontentNode.position = cc.v2(0,(Math.ceil(slotscount/3)-1)*150+75);
        }else{
            this._topcontentNode.position = cc.v2(0,(Math.ceil(slotscount/2)-1)*200+100);
        }
        //同时可以隐藏已经出现的item
        for(let i=2;i<level+1;i++){
            let itemnode = cc.find(cc.js.formatStr('mainnode/topcontent/item%s',i),this.node);
            itemnode.active = false;
        }
    },

    //实例化slots idx从0开始
    initSlotsUI(initnode,idx,colmax,slotscount){
        let slotsdata = cc.vv.gameData.getSlotsListData();
        let wincoin =slotsdata?idx>=slotsdata.coins.length?0:slotsdata.coins[idx]:0;
        let instnode = cc.instantiate(initnode);
        instnode.active = true;
        instnode.parent = this._slotParNode;
        let fslots = instnode.addComponent('TheMagicHanzo_FreeSlots');
        fslots.Init(colmax,wincoin);
        this._slotsScpList.push(fslots);
        if(idx == 2&&slotscount==3){
            instnode.position = cc.v2(0,200);
        }else{
            instnode.position = this.getSlotsUIPos(idx,colmax);
        }
    },

    //计算位置
    getSlotsUIPos(index,colmax){
        let xpos = 0;
        let ypos = 0;
        if(colmax == 2){
            xpos = index%2==0?-150:150;
            ypos = parseInt(index/2)*200;
        }else{
            let idxpos = index%3;
            xpos = idxpos==0?-200:idxpos==1?0:200;
            ypos = parseInt(index/3)*150;
        }
        return cc.v2(xpos,ypos);
    },

    //清除掉实列化出来的slots界面
    clearSlotsUI(){
        this._slotParNode.removeAllChildren();
        this._slotsScpList = [];
    },

});
