
cc.Class({
    extends: require('LMSlots_Logic_Base'),

    properties: {
        
    },

    onLoad () {
        
         //免费游戏脚本
         let script_freegame = this.node.addComponent('TheMagicHanzo_FreeGame');
         cc.vv.gameData.SetGameScript(script_freegame);

         //ui管理
        let uinode = cc.find('safe_node/gameUI',this.node)
        let script_uimgr = uinode.addComponent('TheMagicHanzo_UIMgr');
        cc.vv.gameData.SetUIManagerScript(script_uimgr)

        //多slots管理
        let moreslotsnode = cc.find('safe_node/moreslotsUI',this.node)
        let script_moreslots = moreslotsnode.getComponent('TheMagicHanzo_FreeSlotsMgr');
        cc.vv.gameData.SetMoreSlotsMgr(script_moreslots)

        this._super();
    },

});
