
cc.Class({
    extends: require('LMSlots_Symbol_Base'),

    properties: {
       
    },
    onLoad () {
        
    },

    //播放进入免费动画
    playScatterAnimation(isplay){
        if(this._id != 2){
            return
        }
        let cfg = cc.vv.gameData.getGameCfg();
        let wnode = cc.find(cfg.symbol[this._id].win_node,this.node);
        if(isplay){
            wnode.active = true;
            wnode.getComponent(sp.Skeleton).setAnimation(0,"animation2",true);
        }else{
            wnode.active = false;
        }
    },

    //播放bonus动画(进入转盘游戏)
    playBonusAnimation(isplay){
        if(this._id != 3){
            return
        }
        let cfg = cc.vv.gameData.getGameCfg();
        let wnode = cc.find(cfg.symbol[this._id].win_node,this.node);
        if(isplay){
            wnode.active = true;
            wnode.getComponent(sp.Skeleton).setAnimation(0,"animation2",false);
        }else{
            wnode.active = false;
        }
    },

    //播放bonus数值
    playBonusNum(coin){
        let numnode = cc.find('num',this.node);
        numnode.getComponent(cc.Label).string = Global.convertNumToShort(coin,1000,0);
        numnode.scale = 0;
        cc.tween(numnode).to(0.5,{scale:1},{easing:'backInOut'}).start();
    },

    //清除数字
    clearBonusNum(){
        cc.find('num',this.node).getComponent(cc.Label).string = "";
    },
});
