//免费多slots(主要实现功能旋转/收集)
cc.Class({
    extends: require('LMSlots_Slots_Base'),

    properties: {
        _lastWinCoin:0,
    },

    //初始化 colmax表示最大列数
    Init:function(colmax,wincoin){
        this._topScript = cc.vv.gameData.GetTopScript()
        this._bottomScript = cc.vv.gameData.GetBottomScript()
        this._cfg = cc.vv.gameData.getGameCfg()
        this._col = this._cfg.col
        this._row = this._cfg.row
        this.createFreeReels(this._col,this._row,colmax)
        this.updateWinCoin(wincoin);
    },

     //重写点击旋转按钮调用
     StartMove:function(){
        this._bStopRightnow = null
        this._gameInfo = null

        //每列转起来
        this.MoveReels(this._reels)

        //设置停止时间
        //就是从开始旋转，如果多少秒会开始停止
        this._stopTime = this.GetStopTime()
    },

    OnSpinEnd () {
        console.log('freeslots onspinend');
    },

    //更新wincoin
    updateWinCoin(wincoin){
        let lblwincoin = cc.find('head/getcoin',this.node);
        Global.doRoallNumEff(lblwincoin,this._lastWinCoin,wincoin,1,null,null,0,true);
        this._lastWinCoin = wincoin;
    },

    //显示中奖路线
    //竞品中的显示线路是：先总，后单条循环。目前我们只显示总的
    ShowWinTraceResult(info){
        let allWinIdx = []

        //中奖位置
        for(let i = 0; i < info.zjLuXian.length; i++){
            let item = info.zjLuXian[i]
            for(let idx = 0; idx < item.indexs.length; idx++){
                allWinIdx[item.indexs[idx]] = 1
            }
        }
        if(info.scatterZJLuXian && info.scatterZJLuXian.indexs){
            for(let i = 0; i < info.scatterZJLuXian.indexs.length; i++){
                let val = info.scatterZJLuXian.indexs[i]
                allWinIdx[val] = 1
            }
        }

        //总
        for (const key in allWinIdx) {
            let symbol = this.GetSymbolByIdx(Number(key))
            if(symbol){
                symbol.playWinAnimation()
                symbol.ShowKuang()
            }
        }
    },

    //创建卷轴
    createFreeReels:function(col,row,colmax){
        let reelCmp = this._cfg.scripts.Reels
        for (let i = 0; i < col; i++) {
            let node = cc.find("reels/reel" + (i+1),this.node)
            let scp = node.addComponent('TheMagicHanzo_FreeReel')
            scp.InitReel(i,row,this._topAniNode,colmax)
            this._reels.push(scp)
            
        }
    },

    //显示spine结果
    showMsgSpineResult(msg,cards){
        this._gameInfo = msg
        this.SetSlotsResult(cards)
        this.SetReelStateInfo(cards)
    },

    //slots飞控制
    slotsFly(mainnode,aimpos,flyspine){
        for(let i=1;i<16;i++){
            let symbol = this.GetSymbolByIdx(i);
            if(symbol.GetShowId()==3){
                let flynode = cc.instantiate(flyspine);
                flynode.parent = mainnode;
                flynode.active = true;
                flynode.position = mainnode.convertToNodeSpaceAR(symbol.node.convertToWorldSpaceAR(cc.v2(0,0)))
                Global.SlotsSoundMgr.playEffect('chip_value_collect');
                cc.tween(flynode).to(0.3,{position:aimpos}).start();
            }
        }
    },
});
